import{_ as d,b as o,c as p,g as i}from"./chunks/framework.86O3EbG5.js";const u=JSON.parse('{"title":"古代汉语","description":"","frontmatter":{"title":"古代汉语","subTitle":"古注","author":"oasis","date":"2026-10-21T00:00:00.000Z","tags":["读书笔记"]},"headers":[],"relativePath":"articles/gu-dai-han-yu/6.md","filePath":"articles/gu-dai-han-yu/6.md"}'),r={name:"articles/gu-dai-han-yu/6.md"};function l(n,t,a,e,s,h){return o(),p("div",null,[...t[0]||(t[0]=[i('<p>胡安顺教材第九单元讲训诂，分研究概况、古注的作用、类型、术语、体例。王力通论（十七）（十八）讲注疏体例和术语，以及汉以后注解范围怎样扩大。声训、读为见 <a href="/articles/gu-dai-han-yu/5.html">音韵笔记</a>，通假和破读的界限见 <a href="/articles/gu-dai-han-yu/3.html">汉字笔记</a>。</p><h2 id="传统训诂学的实践与研究概况" tabindex="-1">传统训诂学的实践与研究概况</h2><p>训诂是用当时听得懂的话解释古代的字句。随文作注和通释语义是两条线。</p><p><strong>随文释义</strong>依附在某一本书上，毛传、郑笺、孔疏都是。《尔雅》《说文解字》《方言》《释名》是<strong>通释语义</strong>的专书：《尔雅》按义类编，《说文》据字形说本义，《方言》记地域差别，《释名》用声音推求得名的由来。读注和查这四部书，解决的是不同问题。</p><p>先秦文献里已经有解经的话，《国语》《孟子》解释《诗》《书》就是。系统的注解从汉代开始。先秦典籍传到汉朝，语言变了，又经过口授和传抄，汉人已经不能全读懂。毛亨、孔安国、马融、郑玄做的注，离开先秦还不远，字句解释今天仍然是底子。郑玄遍注群经，《周易》《毛诗》《三礼》《论语》都有他的注。</p><p>唐人距离汉注又有几百年，于是给正文作注，也给旧注作注。这种注解叫<strong>疏</strong>，也叫<strong>正义</strong>。宋人把注和疏合刻，再加上陆德明《经典释文》的音切，成为《十三经注疏》。宋代以前，注和疏本来是两部书。</p><p>注解的范围后来越出经书。史部如裴松之《三国志注》补史料，司马贞《史记索隐》、张守节《史记正义》重在人名、地名和史实。集部如李善《文选注》几乎全力注明出典和词语出处，当时有人说他“释事而忘义”；释义他做得少，但不是完全不释义。子部如郭象《庄子注》、成玄英疏，笔墨多在阐发哲理。</p><p>朱熹的《诗集传》《四书章句集注》《楚辞集注》，往往甩开汉唐旧说，直接从文意入手，平易好读，也常常借注发挥自己的理学。</p><p>清人几乎给每一种重要经典重新作注。段玉裁、王念孙、王引之把文字、音韵用进训诂，主张从声音求字义，解决了不少旧注讲不通的地方。陈奂《诗毛氏传疏》、马瑞辰《毛诗传笺通释》、刘宝楠《论语正义》、焦循《孟子正义》、郭庆藩《庄子集释》，都是读原书时要参考的。缺点是有的注无一字无来历，近于琐碎。刘宝楠给“子曰”的“曰”字可以注上百字。阮元《十三经注疏校勘记》则是校勘，和释义不是一件事。</p><h2 id="古注的作用" tabindex="-1">古注的作用</h2><p>古注首先是阅读的桥梁。文字艰深的书，没有旧注往往无法读下去。具体做的事，王力归纳为几类：</p><ol><li><strong>释词</strong>。马融注《论语》“子者，男子之通称，谓孔子也”，只解释“子”。</li><li><strong>串讲</strong>。把一两句连起来讲，词义夹在句子里。《硕鼠》“三岁贯女，莫我肯顾”，郑笺：“我事女三岁矣，曾无教令恩德来顾眷我。”用“事”解释“贯”，用“眷”解释“顾”。</li><li><strong>通释全章大意</strong>。赵岐《孟子章句》每章之后有“章指”。《寡人之于国也》的章指说：王化之本，在于使民养生丧死之用充足，然后教以礼义。</li><li><strong>注音</strong>。直音、读若、反切都放在注里。见下文术语。</li><li><strong>释事</strong>。人名、地名、史实、典故、名物制度。李善注、裴松之注以这一类为主。仇兆鳌注杜诗，先分段落、讲大意，再逐句注出处。</li><li><strong>校勘</strong>。指出衍文、脱文、讹字。正文传抄会错，注家也有依错字作解的。</li></ol><p>旧注还保住了当时的词义、读音和名物，本身就是汉语史的材料。汉唐人去古未远，说本义、通假，往往比宋以后的望文生义可靠；他们的政治、哲学立场，也会写进注里，不能句句当定论。</p><h2 id="古注的类型" tabindex="-1">古注的类型</h2><p>常见名目：</p><ul><li><strong>传</strong>：阐明经义。毛亨《毛诗故训传》逐字逐句解释《诗经》。《春秋》的《左氏传》《公羊传》《穀梁传》原是独立的书，后来也用来配经。</li><li><strong>注</strong>：解释正文的通称。注的本义是灌入，古书难懂，像水道堵塞，注解是把它疏通。</li><li><strong>笺</strong>：补充并订正已有的传。郑玄《毛诗笺》一方面把毛传简略的地方说清楚，一方面提出和毛传不同的意见，让读者分得开。注疏里“笺云”以下才是郑笺；没有“笺云”的，是毛传。</li><li><strong>章句</strong>：离章辨句。除释词外，还讲句意和章旨。赵岐《孟子章句》、王逸《楚辞章句》。朱熹《大学章句》《中庸章句》沿用这个名称。</li><li><strong>集解（集注）</strong>：有两种，不要混。何晏《论语集解》是汇集各家说法，加上自己的判断。杜预《春秋左氏经传集解》是把经和传合在一起解释，不是汇集众注。读集解先读序，才知道“马曰”“王曰”的马、王是谁。序里没提到的，多半第一次用全名，以后只用姓。</li><li><strong>疏、正义</strong>：既解正文，又解注文。六朝义疏今天完整保存的很少，皇侃《论语义疏》是一部。唐宋人做的疏，大部分收在《十三经注疏》里。</li><li><strong>音义</strong>：以注音为主，兼及义训。陆德明《经典释文》汇集唐以前各家对群经和《老》《庄》的音读。这部书原是独立的，宋代以后才拆开放到各书正文下面。圆圈之后的反切，多数来自《释文》。</li><li><strong>补注</strong>：在旧注之外补其所无、订其失误。王先谦《汉书补注》、孙诒让《墨子间诂》属于这一类。</li></ul><p>《十三经注疏》的注和疏，教材照传统著录如下：</p><table tabindex="0"><thead><tr><th>书</th><th>注</th><th>疏</th></tr></thead><tbody><tr><td>周易</td><td>魏王弼、韩康伯注</td><td>唐孔颖达等正义</td></tr><tr><td>尚书</td><td>旧题汉孔安国传</td><td>唐孔颖达等正义</td></tr><tr><td>诗经</td><td>汉毛亨传、汉郑玄笺</td><td>唐孔颖达等正义</td></tr><tr><td>周礼</td><td>汉郑玄注</td><td>唐贾公彦疏</td></tr><tr><td>仪礼</td><td>汉郑玄注</td><td>唐贾公彦疏</td></tr><tr><td>礼记</td><td>汉郑玄注</td><td>唐孔颖达等正义</td></tr><tr><td>春秋左传</td><td>晋杜预注</td><td>唐孔颖达等正义</td></tr><tr><td>春秋公羊传</td><td>汉何休注</td><td>唐徐彦疏</td></tr><tr><td>春秋穀梁传</td><td>晋范宁注</td><td>唐杨士勋疏</td></tr><tr><td>论语</td><td>魏何晏集解</td><td>宋邢昺疏</td></tr><tr><td>孝经</td><td>唐玄宗注</td><td>宋邢昺疏</td></tr><tr><td>尔雅</td><td>晋郭璞注</td><td>宋邢昺疏</td></tr><tr><td>孟子</td><td>汉赵岐注</td><td>宋孙奭疏</td></tr></tbody></table><p>《尚书》孔安国传是魏晋人托名，所以称旧题。孟子疏旧题孙奭，实出南宋人伪托。公羊、穀梁两疏的作者，注疏本的题名也未可尽信。表上仍按通行题名列出，便于查书。</p><h2 id="古注的体例" tabindex="-1">古注的体例</h2><p>以《毛诗正义》为代表，正文下用双行小字，次序是：</p><ol><li>毛传。不冠“传”字，也不冠“笺云”。《硕鼠》“贯，事也”就是毛传。</li><li>郑笺。以“笺云”起头。</li><li>《经典释文》的音切。常用圆圈隔开，如“贯，古乱反”。</li><li>孔颖达疏。标“疏”。先疏正文，再疏注文。被疏的文字只引起讫两三字，如“硕鼠至得我所”“笺硕大至是徙”，中间用圆圈隔开，然后“正义曰”。</li></ol><p>疏的内容不止翻译。它要说明传笺的出处（常说“《释诂》文”，指《尔雅·释诂》），还考证名物。孔颖达疏《硕鼠》，就用《尔雅·释兽》和陆机《毛诗草木鸟兽虫鱼疏》讨论硕鼠是不是鼫鼠。</p><p>一段里有几条注，疏放在各注之后；只有一条注，疏就紧跟这条注。这是宋以后合刻的排法。</p><p>读疏要知道一个习惯：<strong>疏不破注</strong>。正义以一家旧注为准，注错了也往往顺着讲。和注冲突的说法，疏里不一定看得到。清人的新疏才比较敢破注。</p><h2 id="古注的术语" tabindex="-1">古注的术语</h2><p>王力把常见术语分成释义、声训、破字、注音几组。被释词的位置不同，术语的作用就不同。</p><h3 id="一、曰、为、谓之" tabindex="-1">一、曰、为、谓之</h3><p>被释词放在术语后面，相当于“叫做”。除释义外，专门用来辨析同义词。</p><blockquote><p>谷不熟为饥，蔬不熟为馑。（《尔雅·释天》） 治骨曰切，象曰磋，玉曰琢，石曰磨。（《淇奥》毛传） 骨谓之切，象谓之磋，玉谓之琢，石谓之磨。（《尔雅·释器》）</p></blockquote><p>“饥”和“馑”、“切”和“磋”，用哪一个术语都可以，作用一样。同义词怎么辨析，见 <a href="/articles/gu-dai-han-yu/2.html">词汇笔记</a>。</p><h3 id="二、谓" tabindex="-1">二、谓</h3><p>被释词在“谓”的前面，相当于“指的是”。常用具体解释抽象，或用一般解释特殊。</p><blockquote><p>政谓法教。（孔安国注《论语·为政》） 后生谓少年。（何晏注《论语·子罕》） 美人谓怀王也。（王逸《离骚》注）</p></blockquote><p>“谓之”和“谓”方向相反：一个是“叫做”，一个是“指的是”。</p><h3 id="三、貌" tabindex="-1">三、貌</h3><p>放在形容词或状态词后面，相当于“……的样子”。</p><blockquote><p>沃若，润泽貌。（朱熹注《氓》） 莞尔，小笑貌。（何晏注《论语·阳货》） 崔嵬，高貌也。（王逸《涉江》注）</p></blockquote><p>连绵词、叠音词的注，经常用“貌”。这类词不能拆开讲，见 <a href="/articles/gu-dai-han-yu/2.html">词汇笔记</a>。</p><h3 id="四、犹" tabindex="-1">四、犹</h3><p>用同义词或近义词作注，相当于“等于说”。</p><blockquote><p>侧，犹厓也。（《伐檀》毛传） 谓何，犹云何也。（《节南山》郑笺） 直，犹但也。（朱熹注《孟子·梁惠王上》）</p></blockquote><p>“犹”有时是用引申义解释语境里的意思，和“某，某也”那种径直下定义不完全一样。</p><h3 id="五、之言、之为言" tabindex="-1">五、之言、之为言</h3><p>这两个术语一定是<strong>声训</strong>：解释意义，同时利用同音、双声或叠韵。</p><blockquote><p>萧之言肃也。（郑玄注《论语·季氏》） 政之为言正也，所以正人之不正也；德之为言得也，得于心而不失也。（朱熹注《论语·为政》）</p></blockquote><p>“萧”和“肃”双声，“政”和“正”、“德”和“得”同音。声训可以揭示同源，也可以附会。《释名》“日，实也”“月，阙也”就是用声音硬讲。用声训和用通假一样，要音理和书证两边都站得住，见 <a href="/articles/gu-dai-han-yu/5.html">音韵笔记</a>。</p><h3 id="六、读为、读曰" tabindex="-1">六、读为、读曰</h3><p>用本字说明通假字。</p><blockquote><p>泮读为畔。（《氓》郑笺） 绥读曰妥。（郑玄注《礼记·曲礼》） 倍读曰背。（颜师古注《汉书》）</p></blockquote><p>“泮”“绥”“倍”是借字，“畔”“妥”“背”是本字。</p><h3 id="七、读若、读如" tabindex="-1">七、读若、读如</h3><p>一般用来注音。</p><blockquote><p>哙，咽也。从口，会声。或读若快。（《说文》）</p></blockquote><p>有时也用来破通假，和“读为”作用相同。郑玄注明了，就不会混：</p><blockquote><p>信，读如屈伸之伸，假借字也。（郑玄注《礼记·儒行》）</p></blockquote><p>所以：读为、读曰一定是破字；读若、读如多半是注音，偶尔也破字。</p><h3 id="八、辞-词" tabindex="-1">八、辞（词）</h3><p>指出虚词。毛传：“思，辞也。”（《汉广》“不可求思”）见了“辞也”“词也”，就不要再给这个字找实义。语气词见 <a href="/articles/gu-dai-han-yu/4.html">语法笔记</a>。</p><h3 id="九、浑言、析言-对文、散文" tabindex="-1">九、浑言、析言；对文、散文</h3><p>这是辨析同义词宽严的术语，段玉裁、孔颖达常用。</p><p><strong>浑言</strong>（统言）是笼统说，不加分别；<strong>析言</strong>是分开说，各有专指。</p><blockquote><p>统言之皆称齿、称牙，析言之则前当唇者称齿，后在辅车者称牙。（段玉裁《说文解字注》）</p></blockquote><p><strong>对文</strong>是相对成文，词义分得开；<strong>散文</strong>是单用，可以相通。孔颖达的说法是“对文则异，散文则通”。飞禽称雌雄、走兽称牝牡，对举时有别，散用时可以互称。看到注里说浑言、对文，先判断这是在讲通称还是在讲分别，再决定正文该从宽还是从窄。</p><h3 id="十、衍文、脱文" tabindex="-1">十、衍文、脱文</h3><p>校勘用语。<strong>衍文</strong>（衍字）是传抄刻印多出来的字，<strong>脱文</strong>（夺文）是脱落的字。此外还有讹文（写错）、倒文（次序颠倒）。注里说“衍”“脱”“当为某”，是在改字，要看证据，不能见注就改。</p><h2 id="注音和如字" tabindex="-1">注音和如字</h2><p>早期注音用直音（“某，音某”）和读若。后来注解家改用反切。李善注里的“鼻引”“足俱”是“鼻引切”“足俱切”，省了“切”字，是注音，不是释义。</p><p><strong>如字</strong>表示这个位置按本音读。《礼记·大学》“如恶恶臭，如好好色”，《释文》：</p><blockquote><p>恶恶，上乌路反，下如字。好好，上呼报反，下如字。</p></blockquote><p>前一个“恶”读去声 wù，后一个读恶劣的 è；前一个“好”读去声 hào，后一个读上声 hǎo。</p><p>一个字下面兼注“如字”和另一个反切，表示传统有两读，读法不同，讲法也不同。《论语》“四体不勤，五谷不分”，包咸如字读平声，郑玄读去声，并把“分”讲成“理”。</p><p>用声调区别词义和词性，就是破读。名词“王”平声，称王的动词去声；美好的“好”上声，爱好的“好”去声。有人认为这是六朝经师强生分别。不论来源如何，后来的注音和诗词格律都承认这套读法。今音还分开的，如好 hǎo / hào、恶 è / wù，按词典读；今音已经混同的，读古注时仍要注意旧读表示的词性。破读和通假的分别见 <a href="/articles/gu-dai-han-yu/3.html">汉字笔记</a>。</p><h2 id="使用时的限度" tabindex="-1">使用时的限度</h2><p>汉唐注重字句和读音，保存古义多。宋人注常常“六经注我”，朱熹注里既有文意上的简明，也有理学的发挥。清人注重证据，也重烦琐。</p><p>郭象注《庄子》，“之二虫又何知”下面大讲“自然”“不为”，重点在学说，不在字句。读这类注，先分清哪些是释词，哪些是注家自己的思想。</p><p>阮元校勘记的态度可以当作总则：读古书要依靠注解，不要迷信注解。正文也会因传写而错，注家有的发现了，有的就按错字往下讲。拿不准时，用音韵、字形和同类书证核对，不拿孤零零的一条旧注当结论。</p><h2 id="参考书" tabindex="-1">参考书</h2><ul><li>王力主编《古代汉语》，中华书局（通论十七、十八）</li><li>胡安顺、郭芹纳主编《古代汉语》，中华书局（第九单元：训诂）</li><li>陆德明《经典释文》</li><li>阮元主持校刻《十三经注疏》及《校勘记》</li><li>段玉裁《说文解字注》</li><li>王念孙《读书杂志》、王引之《经义述闻》</li></ul>',79)])])}const b=d(r,[["render",l]]);export{u as __pageData,b as default};
